// Vue 2 (before Vue.observable rewrite)
export default {
  data() {
    return { user: { name: 'Ada', role: null } };
  },
  methods: {
    promote() {
      // BUG: this assignment is invisible to reactivity.
      // 'role' did not exist at data() time, so defineProperty
      // never installed a setter for it — the template never updates.
      this.user.role = 'admin';
      this.notifyRoleChanged(this.user.role);
    },
    promoteCorrectly() {
      // The correct legacy path: $set walks the object, adds
      // getters/setters for the new key, and triggers re-render.
      this.$set(this.user, 'role', 'admin');
      this.notifyRoleChanged(this.user.role);
    },
    notifyRoleChanged(role) {
      console.log('role is now', role);
    }
  }
};

import { reactive } from 'vue';

const state = reactive({
  user: { name: 'Ada', role: null }
});

function promote() {
  // The Proxy set trap intercepts this assignment for ANY key,
  // existing or brand-new, so no $set equivalent is needed.
  state.user.role = 'admin';
  notifyRoleChanged(state.user.role);
}

function notifyRoleChanged(role) {
  console.log('role is now', role);
}

export { state, promote };

// Array holes behave the same way:
const items = reactive([1, 2, 3]);
items[5] = 6; // tracked (array index trap)
items.length = 2; // tracked (length trap)
